using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    private const string BaseUrl = "https://jsonplaceholder.typicode.com";

    [McpServerTool, Description("Fetch a user by their numeric ID from the REST API.")]
    public async Task<string> GetUser(
        [Description("The numeric user ID (1-10)")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching user {UserId}", userId);
        var json = await httpClient.GetStringAsync(
            $"{BaseUrl}/users/{userId}", cancellationToken);
        return json;
    }

    [McpServerTool, Description("List all posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Filter posts by this user ID. Omit to list all posts.")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var url = userId.HasValue
            ? $"{BaseUrl}/posts?userId={userId.Value}"
            : $"{BaseUrl}/posts";

        logger.LogInformation("Listing posts from {Url}", url);
        var json = await httpClient.GetStringAsync(url, cancellationToken);
        return json;
    }

    [McpServerTool, Description("Create a new post for a user.")]
    public async Task<string> CreatePost(
        [Description("The user ID who authors the post")] int userId,
        [Description("The post title")] string title,
        [Description("The post body content")] string body,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating post for user {UserId}", userId);
        var payload = new { userId, title, body };
        var response = await httpClient.PostAsJsonAsync(
            $"{BaseUrl}/posts", payload, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

